import org.junit.Test;
import org.mockito.Mockito;

public class TextNodeTest {

    @Test
    public void createTextNode_TextNodeCreatedCorrectly() {
        // Given
        String text = "Hello World";

        // When
        TextNode textNode = new TextNode(text);

        // Then
        assertNotNull(textNode);
        assertEquals("#text", textNode.nodeName());
        assertEquals(text, textNode.text());
    }

    @Test
    public void createTextNode_FromEncodedTextCreatedCorrectly() {
        // Given
        String encodedText = "&lt;Hello&gt; World";

        // When
        TextNode textNode = TextNode.createFromEncoded(encodedText);

        // Then
        assertNotNull(textNode);
        assertEquals("#text", textNode.nodeName());
        assertEquals("Hello World", textNode.text());
    }

    @Test
    public void splitText_TextNodeSplitCorrectly() {
        // Given
        String text = "Hello World";
        int offset = 5;

        // When
        TextNode tailNode = new TextNode(text.splitText(offset));

        // Then
        assertNotNull(tailNode);
        assertEquals("#text", tailNode.nodeName());
        assertEquals("World", tailNode.text());

        assertNotNull(new Node() {
            @Override
            public String getWholeText() {
                return "Hello";
            }

            @Override
            public boolean isBlank() {
                return true;
            }
        });
    }

